"""Multiplier shapes of the octic class: for each of the 61 targets (targets.py) the subgroups H of Z_v* (generated by one or two elements) with -1 not in H,
|H| > 1 (even order allowed for composite v) and at most NMAX orbits.
usage: python3 targets.py && python3 shapes_oct.py NMAX      reads runs/octic_targets.json, writes runs/oct_shapes_n<NMAX>.json, prints the counts per n
module: gen_sub(v, gens), norb(v, H), shapes(v, nmax)"""
import json, sys, os
from math import gcd
def gen_sub(v,gens):
    H={1};fr=[1]
    while fr:
        x=fr.pop()
        for g in gens:
            y=x*g%v
            if y not in H: H.add(y);fr.append(y)
    return frozenset(H)
def norb(v,H):
    seen=bytearray(v);c=0
    for g in range(v):
        if not seen[g]:
            c+=1
            for h in H: seen[g*h%v]=1
    return c
def shapes(v,nmax):
    units=[h for h in range(1,v) if gcd(h,v)==1]
    cyc={}
    for h in units:
        S=gen_sub(v,[h])
        if (v-1) not in S and v>2: cyc.setdefault(S,h)
    subs=dict((S,[h]) for S,h in cyc.items())
    items=list(cyc.items())
    for i in range(len(items)):
        for j in range(i+1,len(items)):
            S=gen_sub(v,[items[i][1],items[j][1]])
            if (v-1) not in S and S not in subs: subs[S]=[items[i][1],items[j][1]]
    out=[]
    for S,g in subs.items():
        if len(S)<2: continue
        n=norb(v,S)
        if n<=nmax: out.append((n,len(S),g))
    out.sort(); return out
if __name__=="__main__":
    nmax=int(sys.argv[1]); res={}
    tg=json.load(open('runs/octic_targets.json'))
    for v,m,k in tg:
        sh=shapes(v,nmax)
        if sh: res[v]=(m,sh)
    os.makedirs('runs',exist_ok=True)
    json.dump({str(k):v for k,v in res.items()},open(f'runs/oct_shapes_n{nmax}.json','w'))
    print(len(res),'targets with shapes n<=',nmax,'; total shapes',sum(len(x[1]) for x in res.values()))
    from collections import Counter
    c=Counter(n for v,(m,sh) in res.items() for n,o,g in sh); print('by n:',sorted(c.items()))
    for v,(m,sh) in sorted(res.items()): print(v,m,[(n,o) for n,o,g in sh])
